    DB 0C1h, 0C5h, 10h    ; ROL BP, 16   ; filler: the queue fills, the bus idles
    DB 0B8h, 00h, 0F0h    ; MOV AW, F000h
    DB 8Eh, 0C0h    ; MOV DS1, AW
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 00h    ; MOV word DS1:[FFE8h], 0000h
    DB 26h, 0C6h, 06h, 0EBh, 0FFh, 4Eh    ; MOV byte DS1:[FFEBh], 4Eh
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 42h    ; INC DW
    DB 42h    ; INC DW
    DB 0EFh    ; OUT DW, AW
    DB 0B8h, 00h, 0F0h    ; MOV AW, F000h
    DB 8Eh, 0C0h    ; MOV DS1, AW
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 00h, 00h    ; MOV word DS1:[FFE8h], 0000h
    DB 0BAh, 00h, 0FFh    ; MOV DW, FF00h
    DB 0EEh    ; OUT DW, AL
    DB 0F4h    ; HALT
    DB 0EBh, 0FEh    ; BR $
